#!/bin/bash
# CSA Loom — UAT smoke runner for the jumpbox.
#
# Self-contained on purpose: the jumpbox has no checkout, so the smoke test is
# pasted in base64 and decoded here.
#
# THE ARTIFACT DIRECTORY IS THE SECURITY-RELEVANT PART OF THIS SCRIPT.
# It used to be `mkdir -p /tmp/loom-uat`. /tmp is world-writable and the
# jumpbox is multi-user, so any other local user could pre-create that path —
# as a directory they own, or as a symlink into one — and `mkdir -p` would
# succeed against BOTH without a word. The artifacts are full-page screenshots
# of an AUTHENTICATED console session (CodeQL js/insecure-temporary-file,
# alerts #323 / #330).
#
# A hardened creator was added to the repo for those alerts and this script
# never called it — the embedded copy below predated it and ran a bare
# mkdirSync. So the directory is now created HERE, once, before node starts,
# and the embedded copy does no mkdir at all.
set -euo pipefail

ART_DIR="${LOOM_UAT_ARTIFACT_DIR:-$HOME/.loom-uat}"

# -L before -d: a symlink to a directory answers yes to -d, so checking -d
# first would follow exactly the link this refuses.
if [ -L "$ART_DIR" ]; then
  echo "Refusing to use $ART_DIR: it is a symlink." >&2
  exit 1
fi
if [ -e "$ART_DIR" ] && [ ! -d "$ART_DIR" ]; then
  echo "Refusing to use $ART_DIR: it exists and is not a directory." >&2
  exit 1
fi

mkdir -m 700 -p "$ART_DIR"
# -m only applies to directories mkdir CREATES. One made earlier by a plain
# `mkdir -p` is 0755 under the default umask — ours, and world-readable. Repair
# it rather than trust the create flag.
chmod 700 "$ART_DIR"
export LOOM_UAT_ARTIFACT_DIR="$ART_DIR"

cd "$ART_DIR"

# The embedded smoke test. Regenerate with:
#   node -e "console.log(require('fs').readFileSync('apps/fiab-console/tests/uat-console-smoke.mjs').toString('base64'))"
# scripts/ci/check-temp-artifact-safety.mjs DECODES this blob and scans it, so a
# stale copy that reintroduces a fixed /tmp path fails CI instead of shipping.
echo '' | base64 -d > uat-console-smoke.mjs

if [ ! -d node_modules/playwright ]; then
  npm init -y >/dev/null
  npm install playwright --no-audit --no-fund >/dev/null 2>&1
fi

node uat-console-smoke.mjs "$@" 2>&1
